-- Demo-only totals:
SELECT 'plans' AS entity, count(*) AS rows FROM wellness_plan WHERE name LIKE '[DEMO-W48] %'
UNION ALL SELECT 'habits', count(*) FROM habit h JOIN wellness_plan p ON p.id=h.plan_id WHERE p.name LIKE '[DEMO-W48] %'
UNION ALL SELECT 'check_ins', count(*) FROM check_in c JOIN habit h ON h.id=c.habit_id JOIN wellness_plan p ON p.id=h.plan_id WHERE p.name LIKE '[DEMO-W48] %'
UNION ALL SELECT 'settings', count(*) FROM evaluation_setting s JOIN wellness_plan p ON p.id=s.plan_id WHERE p.name LIKE '[DEMO-W48] %';
